//! End-to-end detection per kind: at least 20 positive and 20 negative cases
//! each (M2 acceptance, docs/systemdesign.md section 17).
//!
//! Every case runs the full pipeline (normalize, detect, score, resolve,
//! decide) on spoken or written Turkish. Identifier vectors were generated by
//! an independent Python implementation, never by the code under test.

use ortu_core::{
    Analyzer, EntityKind, Policy, SessionHints, Speaker, Turn, TurnAnalysis, ValidatorOutcome,
    Weights,
};

const UNITS: [&str; 10] = [
    "sıfır", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz",
];

fn analyzer() -> Analyzer {
    Analyzer::new(
        ortu_tr::default_detectors(),
        ortu_tr::default_cue_rules(),
        Weights::default(),
        Policy::default(),
    )
}

fn analyze_as(speaker: Speaker, text: &str, hints: &SessionHints) -> TurnAnalysis {
    let turn = Turn::from_text(0, speaker, text, 0, 10_000);
    analyzer().analyze_turn(&turn, hints, 0)
}

fn analyze(text: &str) -> TurnAnalysis {
    analyze_as(Speaker::Caller, text, &SessionHints::default())
}

/// Values of the entities of `kind`.
fn values(analysis: &TurnAnalysis, kind: EntityKind) -> Vec<String> {
    analysis
        .entities
        .iter()
        .filter(|e| e.kind == kind)
        .map(|e| e.value.expose_secret().to_owned())
        .collect()
}

/// Reads a digit string digit by digit.
fn spoken_digits(digits: &str) -> String {
    digits
        .bytes()
        .map(|b| UNITS[usize::from(b - b'0')])
        .collect::<Vec<_>>()
        .join(" ")
}

/// Splits a digit string into groups of `size` digit tokens.
fn grouped(digits: &str, size: usize) -> String {
    digits
        .as_bytes()
        .chunks(size)
        .map(String::from_utf8_lossy)
        .collect::<Vec<_>>()
        .join(" ")
}

