// ---------------------------------------------------------------- Names

fn names(analysis: &TurnAnalysis) -> Vec<(EntityKind, String)> {
    analysis
        .entities
        .iter()
        .filter(|e| {
            matches!(
                e.kind,
                EntityKind::PersonName | EntityKind::PersonSurname | EntityKind::FullName
            )
        })
        .map(|e| (e.kind, e.value.expose_secret().to_owned()))
        .collect()
}

#[test]
fn name_positive_cases() {
    use EntityKind::{FullName, PersonName, PersonSurname};
    let cases: [(&str, EntityKind, &str); 20] = [
        ("adım Ahmet", PersonName, "ahmet"),
        ("adım Ahmet Yılmaz", FullName, "ahmet yılmaz"),
        ("ismim Ayşe", PersonName, "ayşe"),
        ("ismim Ayşe Kaya", FullName, "ayşe kaya"),
        ("soyadım Demir", PersonSurname, "demir"),
        ("soyismim Öztürk", PersonSurname, "öztürk"),
        ("adım soyadım Mehmet Çelik", FullName, "mehmet çelik"),
        ("ad soyad Zeynep Arslan", FullName, "zeynep arslan"),
        ("merhaba adım Deniz", PersonName, "deniz"),
        ("adım Umut Yıldız", FullName, "umut yıldız"),
        ("İSMİM İREM", PersonName, "irem"),
        ("Ahmet Bey", PersonName, "ahmet"),
        ("Fatma Hanım", PersonName, "fatma"),
        ("teşekkürler Selim Bey", PersonName, "selim"),
        ("adım Gül ııı", PersonName, "gül"),
        ("adım ııı Barış", PersonName, "barış"),
        ("benim adım Elif Şahin", FullName, "elif şahin"),
        ("ismim Can, borcumu soracaktım", PersonName, "can"),
        ("adım Kemal ve şikayetim var", PersonName, "kemal"),
        ("evet Hülya Hanım buyrun", PersonName, "hülya"),
    ];
    for (text, kind, value) in cases {
        assert_eq!(names(&analyze(text)), [(kind, value.to_owned())], "{text}");
    }
    assert!(cases.len() >= 20);
}

#[test]
fn names_after_a_form_of_address() {
    use EntityKind::{FullName, PersonName};
    assert_eq!(
        names(&analyze("Sayın Ahmet Yılmaz, borcunuz 1250 TL")),
        [(FullName, "ahmet yılmaz".to_owned())]
    );
    assert_eq!(
        names(&analyze("sayın Ayşe Hanım")),
        [(PersonName, "ayşe".to_owned())]
    );
    for text in ["Sayın müşterimiz", "sayın yetkili", "Sayın ilgili"] {
        assert_eq!(names(&analyze(text)), Vec::new(), "{text}");
    }
}

#[test]
fn name_answer_after_an_assistant_question() {
    let bot = analyze_as(
        Speaker::Bot,
        "adınızı ve soyadınızı alabilir miyim",
        &SessionHints::default(),
    );
    assert_eq!(bot.expecting_next, Some(EntityKind::PersonName));
    let hints = SessionHints {
        expecting: bot.expecting_next,
        ..SessionHints::default()
    };
    let answer = analyze_as(Speaker::Caller, "Elif Şahin", &hints);
    assert_eq!(
        names(&answer),
        [(EntityKind::FullName, "elif şahin".to_owned())]
    );
}

#[test]
fn name_negative_cases() {
    let cases = [
        "adım adım ilerliyoruz",
        "ben de aynı şeyi düşünüyorum",
        "ben belediyeden arıyorum",
        "Müdür Bey ile görüşmek istiyorum",
        "Ahmet Yesevi caddesindeyim",
        "deniz kenarında oturuyorum",
        "umut ediyorum",
        "adım atıyorum",
        "bey",
        "hanım",
        "ismim ne olacak",
        "adım on iki",
        "Başkan Bey nerede",
        "adım şey",
        "soyadım ııı",
        "Doktor Hanım çıktı mı",
        "adımı attım",
        "isim soyisim bilgisi gerekli",
        "tamam hanım efendi",
        "yarın gelirim",
    ];
    for text in cases {
        assert_eq!(names(&analyze(text)), Vec::new(), "{text}");
    }
    assert!(cases.len() >= 20);
}

#[test]
fn agent_names_are_never_masked() {
    let hints = SessionHints {
        agent_names: vec!["türkay".to_owned()],
        ..SessionHints::default()
    };
    let analysis = analyze_as(Speaker::Bot, "merhaba adım Türkay", &hints);
    assert_eq!(names(&analysis), Vec::new());
}

#[test]
fn a_long_answer_is_not_taken_as_a_name() {
    let hints = SessionHints {
        expecting: Some(EntityKind::PersonName),
        ..SessionHints::default()
    };
    let answer = analyze_as(
        Speaker::Caller,
        "Elif ama önce bir şey soracağım size",
        &hints,
    );
    assert_eq!(names(&answer), Vec::new());
}
